const input = $input.first().json.body || $input.first().json;
const poll = input.poll; if (!poll || typeof poll !== 'object' || !poll.question) throw new Error('poll with question is required');
const options = Array.isArray(poll.options) ? poll.options.map(o => ({ text: String(o.text || ''), voteCount: Math.max(0, Number(o.voteCount) || 0) })) : [];
const totalVotes = options.reduce((s, o) => s + o.voteCount, 0);
const prompt = `Summarize this community poll as a neutral governance record. Only use the aggregate vote counts supplied. Do not infer individual voters, representativeness, quorum, legal validity, approval authority or consent unless explicit rules and validated data are included. If poll is still open, clearly label results preliminary. Do not create or cast votes.
Poll: ${JSON.stringify({ id: poll.id || null, question: String(poll.question).slice(0, 1000), description: poll.description || null, anonymous: Boolean(poll.anonymous), closed: Boolean(poll.closed), closesOn: poll.closesOn || null, options, totalVotes, quorumRule: input.quorumRule || null })}
Return JSON {"statusLabel":"PRELIMINARY|CLOSED_RESULTS","summary":"...","optionObservations":["..."],"participationNotes":["..."],"quorumAssessment":"NOT_ASSESSED|...","recommendedGovernanceFollowUp":["..."]}.`;
return [{ json: { pollId: poll.id || null, question: poll.question, totalVotes, prompt } }];
